//! Babel platform data the linter ports run on, tracked in `assets/` (`tools/lint-parity/generate.mjs`
//! regenerates the lint data from a Babel checkout).

/// Gold linter configuration for the gold-non-bg variant of every language and its rule
/// tables (generated by `tools/lint-parity/generate.mjs`).
pub const LINT_DATA_JSON: &str = include_str!("../assets/babel-lint-data.json");

/// Babel's localized error-category bucket and category names, by language.
pub const ERROR_CATEGORY_NAMES_JSON: &str = include_str!("../assets/error-category-names.json");

/// Lint parity corpus with the issues Babel's linter and the Helper custom linter report for
/// each case (generated by `tools/lint-parity/generate.mjs`), for the linter ports' tests.
///
/// The corpus is a private transcript fixture that ships in the Babel data bundle
/// (`tools/babel-data.json`), not in the tree. It is read from `$EXAUDIO_PARITY_DATA`, else
/// from the stage `tools/update-babel-data.ps1 -Fetch` unpacks (`target/babel-data`). `None`
/// (with a note on stderr) when the file is absent, so the parity tests skip on checkouts
/// without the bundle.
#[cfg(test)]
pub fn lint_parity_json(test: &str) -> Option<String> {
    use std::path::PathBuf;

    let dir = std::env::var_os("EXAUDIO_PARITY_DATA")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/babel-data")
        });
    let path = dir.join("lint-parity.json");
    match std::fs::read_to_string(&path) {
        Ok(json) => Some(json),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            eprintln!(
                "{test}: skipped, no lint parity corpus at {} (fetch the Babel data bundle with \
                 `powershell -File tools/update-babel-data.ps1 -Fetch`, or point \
                 EXAUDIO_PARITY_DATA at its unpacked directory)",
                path.display()
            );
            None
        }
        Err(error) => panic!("read {}: {error}", path.display()),
    }
}
